parameters.jsCode:
// Turn Neo4j Query API rows into one compact text block for the LLM.
// Each hit keeps its source URL so the agent can cite it.
const d = $input.first().json.data;
const rows = d.values.map(v => Object.fromEntries(d.fields.map((f, i) => [f, v[i]])));
const result = rows.map((r, i) =>
  `[${i + 1}] ${r.artist} - ${r.album} | section: ${r.section} | score: ${r.score.toFixed(3)} | source: ${r.source}\n${r.text}`
).join('\n\n');
return [{ json: { result: result || 'No matching text found.' } }];
